#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEngine.UI;using UnityEditor;
using HeartOfTheRain.App.Profile;using HeartOfTheRain.App.PreLevel;using HeartOfTheRain.App.Localization;
namespace HeartOfTheRain.Verification {
    public static class RainCupVerification {
        [Serializable] sealed class Report {public string utc,status,unity,scope="Native Unity Cup transactions, old-save compatibility, file fault recovery, atomic first-clear scoring, configuration snapshots, assets/layout/font checks. Local practice only; Android rendering/input are separate.";public int checks;public List<string> cases=new List<string>(),failures=new List<string>();}
        [Serializable] sealed class Envelope {public int format=1;public string payload,sha256;}
        static Report report;static RainCupRules rules;static string root;
        static void Check(bool ok,string name){report.checks++;if(!ok)throw new Exception(name);}
        static void Throws<T>(Action a) where T:Exception {try{a();}catch(T){Check(true,"Expected rejection");return;}throw new Exception("Expected "+typeof(T).Name);}
        static void Case(string name,Action action){try{action();report.cases.Add(name);}catch(Exception e){report.failures.Add(name+": "+e);}}
        static PlayerProfile New(int completed=10){var p=PlayerProfile.New(new[]{5,5,3,2});p.completed=completed;p.currentLevel=Math.Min(50,completed+1);p.stars=completed;return p;}
        static ProfileService Memory(int completed=10)=>new ProfileService(new MemoryProfileRepository(New(completed)));
        static string Reserve(ProfileService s,int level){string id=Guid.NewGuid().ToString("N");s.Reserve(id,level,"fixture-level-config",new int[4],50,1);s.CommitStart(id);return id;}
        static AttemptRecord Win(ProfileService s,int level,long now){string id=Reserve(s,level);return s.Win(id,now);}
        sealed class ConflictRepository:IProfileRepository {
            readonly MemoryProfileRepository inner=new MemoryProfileRepository(New());public bool Inject;
            public PlayerProfile Read()=>inner.Read();public PlayerProfile Commit(long revision,PlayerProfile next){if(Inject){Inject=false;var p=inner.Read();p.coins++;inner.Commit(revision,p);throw new ProfileConflictException();}return inner.Commit(revision,next);}
        }
        public static void Run(){
            report=new Report{utc=DateTime.UtcNow.ToString("o"),unity=Application.unityVersion};root=Path.GetFullPath("../.verification-cache/RainCup/Native-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);rules=JsonUtility.FromJson<RainCupRules>(Resources.Load<TextAsset>("HOTR_RainCup/Rules").text);
            Case("Approved resource, timer arithmetic and unavailable production adapter",()=>{
                rules.Validate();Check(rules.unlockClears==10&&rules.durationSeconds==172800&&rules.rivalFinalScores.Length==4,"Approved practice eligibility/duration");Check(rules.rankRewards.Select(g=>g.coins).SequenceEqual(new[]{300,200,100,50,50})&&rules.rankRewards[0].starting.SequenceEqual(new[]{1,1,0,0})&&rules.rankRewards[1].tools.SequenceEqual(new[]{1,0,0,0})&&rules.rankRewards.All(g=>g.stars==0),"Approved prize table");Check(RainCupText.Timer(172800)=="48:00:00"&&RainCupText.Timer(172799)=="47:59:59","No rounding into incorrect hour");var off=new UnavailableRainCupService();Check(off.View().state=="Unavailable"&&!off.View().development&&off.CaptureWinTime()==null,"Production unavailable");Throws<InvalidOperationException>(()=>off.Join(Guid.NewGuid().ToString("N")));Throws<InvalidOperationException>(()=>off.Claim(Guid.NewGuid().ToString("N")));
            });
            Case("Existing version-one profile loads without an event field or data reset",()=>{
                var p=New();p.coins=4321;p.tools[0]=7;string json=JsonUtility.ToJson(p);Check(json.Contains("\"rainCups\":[]"),"New event field present");json=json.Replace(",\"rainCups\":[]","");Check(!json.Contains("rainCups"),"Fixture represents preceding save");string dir=Path.Combine(root,"legacy");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"profile.json"),JsonUtility.ToJson(new Envelope{payload=json,sha256=ProfileJson.Hash(json)}));var loaded=new FileProfileRepository(dir,()=>throw new Exception("Must not reset")).Read();Check(loaded.coins==4321&&loaded.stars==10&&loaded.completed==10&&loaded.tools[0]==7&&loaded.rainCups.Count==0&&loaded.pendingGift==null,"All preceding balances/identity preserved");Check(File.ReadAllText(Path.Combine(dir,"profile.json")).Contains(ProfileJson.Hash(json)),"Loading does not rewrite old save");
            });
            Case("Join eligibility, idempotent commands, no overlapping cups or attempts",()=>{
                long now=1000;var s=Memory(9);var cup=new DevelopmentRainCupService(s,rules,()=>now);Check(cup.View().state=="Locked","Unlock requires ten first clears");Throws<InvalidOperationException>(()=>cup.Join(Guid.NewGuid().ToString("N")));Win(s,10,now);string id=Guid.NewGuid().ToString("N");cup.Join(id);cup.Join(id);Check(s.Read().rainCups.Count==1&&cup.View().state=="Active"&&cup.Remaining(cup.View())==172800,"One command, one cup");Throws<InvalidOperationException>(()=>cup.Join(Guid.NewGuid().ToString("N")));Throws<InvalidOperationException>(()=>cup.Claim(id));var active=Memory();Reserve(active,11);Throws<InvalidOperationException>(()=>new DevelopmentRainCupService(active,rules,()=>now).Join(Guid.NewGuid().ToString("N")));var finished=Memory(50);Check(new DevelopmentRainCupService(finished,rules,()=>now).View().state=="Exhausted","No Cup when no new boards remain");
            });
            Case("Atomic score with model win; replay, loss and restart recovery cannot score",()=>{
                long now=1000;var s=Memory();var cup=new DevelopmentRainCupService(s,rules,()=>now);string run=cup.Join(Guid.NewGuid().ToString("N"));string first=Reserve(s,11);var won=s.Win(first,cup.CaptureWinTime());s.Win(first,now+1);Check(won.rainCupPoint==1&&s.Read().completed==11&&s.Read().rainCups[0].points==1,"One saved first clear and point");Win(s,11,now+2);Check(s.Read().rainCups[0].points==1,"Replay earns no points");string lost=Reserve(s,12);s.Lose(lost);s.Lose(lost);string interrupted=Reserve(s,12);s.RecoverInterrupted();s.RecoverInterrupted();Check(s.Read().rainCups[0].points==1&&s.Read().lives==3,"Loss and interruption earn no points; one life each");Check(s.Read().attempts.First(a=>a.id==first).rainCupId==run,"Attempt bound to its original Cup");
            });
            Case("Exclusive end boundary, tie ranks, rollback guard and frozen finish",()=>{
                long now=1000;var s=Memory();var cup=new DevelopmentRainCupService(s,rules,()=>now);string id=cup.Join(Guid.NewGuid().ToString("N"));now+=rules.durationSeconds-1;Win(s,11,cup.CaptureWinTime().Value);now++;Win(s,12,cup.CaptureWinTime().Value);Check(s.Read().rainCups[0].points==1&&s.Read().completed==12,"Deadline win progresses campaign without late event point");Check(cup.View().state=="Finished","Boundary finalizes once");now=1;Check(cup.View().state=="Finished"&&cup.Remaining(cup.View())==0,"Clock rollback cannot reopen finished cup");Check(RainCupModel.Rank(24,new[]{24,18,12,6})==1&&RainCupModel.Rank(18,new[]{24,18,12,6})==2,"Ties share rank and prize");cup.Claim(id);Check(s.Read().coins==1400,"Fifth-place grant plus two first-clear grants");
            });
            Case("Each finishing rank credits approved shared stock exactly once",()=>{
                int[] points={30,20,13,7,0};for(int rank=1;rank<=5;rank++){long now=1000;var s=Memory();var cup=new DevelopmentRainCupService(s,rules,()=>now);string id=cup.Join(Guid.NewGuid().ToString("N"));for(int i=0;i<points[rank-1];i++)Win(s,11+i,now+i);now+=rules.durationSeconds+1;Check(cup.View().run.finalRank==rank,"Final rank "+rank);var grant=cup.Claim(id);Check(grant.coins==rules.rankRewards[rank-1].coins&&cup.Claim(id)==null,"Idempotent prize "+rank);var p=s.Read();Check(p.coins==1250+50*points[rank-1]+grant.coins&&p.stars==10+points[rank-1]&&p.lives==5,"No star/life mutation "+rank);Check(p.starting[0]==5+grant.starting[0]&&p.starting[1]==5+grant.starting[1]&&p.tools[0]==3+grant.tools[0]&&p.rewards.Count==1,"Shared stock "+rank);now+=10000000;Check(cup.View().state=="Claimed"&&cup.Claim(id)==null,"No claim expiry/regrant "+rank);}}
            );
            Case("In-flight rules and rewards survive config revisions and mutable snapshots",()=>{
                long now=1000;var s=Memory();var config=rules.Copy();var cup=new DevelopmentRainCupService(s,config,()=>now);string id=cup.Join(Guid.NewGuid().ToString("N"));config.rankRewards[4].coins=999;config.durationSeconds=5;var view=cup.View();view.run.rules.rankRewards[4].coins=888;var next=rules.Copy();next.version="practice-next";next.rankRewards[4].coins=777;cup=new DevelopmentRainCupService(s,next,()=>now);now+=rules.durationSeconds;Check(cup.Claim(id).coins==50&&s.Read().coins==1300,"Joined rules remain final");Check(cup.View().run.rules.version==rules.version,"Original schedule version retained");cup.Join(Guid.NewGuid().ToString("N"));Check(cup.View().run.rules.version=="practice-next","Next cup uses new config");
            });
            Case("File interruption before/after join, win and claim remains atomic on reopen",()=>{
                foreach(string operation in new[]{"join","win","claim"})foreach(string phase in new[]{"TempFlushed","Committed"}){
                    string dir=Path.Combine(root,operation+phase),id=Guid.NewGuid().ToString("N"),attempt="";long now=1000;var repo=new FileProfileRepository(dir,()=>New());var s=new ProfileService(repo);var cup=new DevelopmentRainCupService(s,rules,()=>now);s.Read();if(operation!="join")cup.Join(id);if(operation=="win")attempt=Reserve(s,11);if(operation=="claim")now+=rules.durationSeconds;
                    repo.Checkpoint=p=>{if(p==phase)throw new IOException("Injected "+operation+phase);};Throws<IOException>(()=>{if(operation=="join")cup.Join(id);else if(operation=="win")s.Win(attempt,now);else cup.Claim(id);});
                    s=new ProfileService(new FileProfileRepository(dir,()=>throw new Exception("Must not reset")));cup=new DevelopmentRainCupService(s,rules,()=>now);if(operation=="join"){cup.Join(id);cup.Join(id);Check(s.Read().rainCups.Count==1,"Join once "+phase);}else if(operation=="win"){Check(s.Read().completed==(phase=="Committed"?11:10)&&s.Read().rainCups[0].points==(phase=="Committed"?1:0),"Win/point atomic "+phase);s.Win(attempt,now);s.Win(attempt,now+1);Check(s.Read().rainCups[0].points==1&&s.Read().coins==1300,"One recovered win "+phase);}else{cup.Claim(id);cup.Claim(id);Check(s.Read().coins==1300&&s.Read().rewards.Count==1&&s.Read().rainCups[0].state=="Claimed","One recovered grant "+phase);}
                }
            });
            Case("CAS retries, overflow and unavailable optional clock preserve campaign state",()=>{
                long now=1000;var repo=new ConflictRepository();var s=new ProfileService(repo);var cup=new DevelopmentRainCupService(s,rules,()=>now);repo.Inject=true;string id=cup.Join(Guid.NewGuid().ToString("N"));string attempt=Reserve(s,11);repo.Inject=true;s.Win(attempt,now);now+=rules.durationSeconds;repo.Inject=true;cup.Claim(id);Check(s.Read().coins==1353&&s.Read().rainCups.Count==1&&s.Read().rainCups[0].points==1&&s.Read().rewards.Count==1,"CAS preserves concurrent credit and one join/score/prize");
                s=Memory();cup=new DevelopmentRainCupService(s,rules,()=>now);id=cup.Join(Guid.NewGuid().ToString("N"));s.Change(p=>p.coins=int.MaxValue);now+=rules.durationSeconds;Throws<OverflowException>(()=>cup.Claim(id));Check(s.Read().rainCups[0].state=="Active"&&s.Read().rewards.Count==0&&s.Read().coins==int.MaxValue,"Overflow rolls back finish and grant together");
                s=Memory();cup=new DevelopmentRainCupService(s,rules,()=>1000);cup.Join(Guid.NewGuid().ToString("N"));cup=new DevelopmentRainCupService(s,rules,()=>throw new IOException("Invalid clock"));attempt=Reserve(s,11);s.Win(attempt,cup.CaptureWinTime());Check(s.Read().completed==11&&s.Read().rainCups[0].points==0,"Unavailable practice time does not block a campaign win or fabricate a score");
            });
            Case("Native assets, bounds and glyphs across five locales and all panel states",()=>{
                var assets=AssetDatabase.LoadAssetAtPath<PreLevelAssets>("Assets/HeartOfTheRain/App/PreLevel/PreLevelAssets.asset");var go=new GameObject("Cup font verification",typeof(RectTransform),typeof(Text));var text=go.GetComponent<Text>();text.font=assets.home.boldFont;text.verticalOverflow=VerticalWrapMode.Truncate;text.supportRichText=false;int old=GameLocale.Current;
                try{for(int locale=0;locale<5;locale++){GameLocale.Select(locale);foreach(int width in new[]{320,393,768})foreach(int state in Enumerable.Range(0,10)){
                    long now=1000;var s=Memory(state==0?0:state==8?50:10);IRainCupService cup=new DevelopmentRainCupService(s,rules,()=>now);if(state>=2&&state<=7){string id=cup.Join(Guid.NewGuid().ToString("N"));if(state>=4){Win(s,11,now);now+=rules.durationSeconds;}if(state==6)cup.Claim(id);}if(state==9)cup=new UnavailableRainCupService();var snap=cup.View();var view=new RainCupView{snapshot=snap,remaining=cup.Remaining(snap),showPrizes=state==3||state==5||state<=1,error=state==7};var f=RainCupLayout.Build(width,568,view);var panel=f.elements.First(e=>e.id=="panel");
                    // Every element under the panel (the R1 frame nests header/viewport/body/footer), measured as RainCupPage renders it; scroll-body rows may run past the panel height and player names are ellipsized by the page.
                    var design=RainCupDesignAssets.Load();var byId=f.elements.ToDictionary(e=>e.id);
                    foreach(var e in f.elements){if(e.id=="panel")continue;float ax=e.x,ay=e.y;bool inPanel=false,scrolls=e.id=="body";for(var p=e;!string.IsNullOrEmpty(p.parent)&&byId.TryGetValue(p.parent,out p);){if(p.id=="panel"){inPanel=true;break;}if(p.id=="body")scrolls=true;ax+=p.x;ay+=p.y;}if(!inPanel)continue;
                        bool overhang=e.id=="close"||e.parent=="close";// the round close button straddles the panel corner by design
                        Check(overhang||ax>=-.01f&&ax+e.width<=panel.width+.01f&&(scrolls||ay>=-.01f&&ay+e.height<=panel.height+.01f),"Contained "+e.id);if(e.kind=="sprite")Check(design.Find(e.asset)!=null||assets.Find(e.asset)!=null,"Approved asset "+e.asset);if(e.kind!="text"||e.id.StartsWith("name-",StringComparison.Ordinal))continue;
                        bool bold=e.id=="title"||e.id.Contains("label")||e.id.Contains("title")||e.id.Contains("quantity")||e.id.StartsWith("rank-",StringComparison.Ordinal)||e.id.StartsWith("points-",StringComparison.Ordinal)||e.id=="score-count"||e.id=="heading"||e.id=="progress-count",widthFit=e.id=="primary-label"||e.id=="standings-label"||e.id=="rewards-label"||e.id=="list-heading";text.font=bold?design.shared.shared.titleFont:design.shared.shared.bodyFont;text.text=e.text;text.fontSize=e.fontSize;((RectTransform)text.transform).sizeDelta=new Vector2(e.width,e.height);
                        text.horizontalOverflow=widthFit?HorizontalWrapMode.Overflow:HorizontalWrapMode.Wrap;if(widthFit){while(text.fontSize>(e.id=="primary-label"?14:e.id=="list-heading"?8:12)&&text.preferredWidth>e.width+.01f)text.fontSize--;}else while(text.fontSize>9&&text.preferredHeight>e.height+.01f)text.fontSize--;bool paragraph=!widthFit;text.font.RequestCharactersInTexture(text.text,text.fontSize);Check((paragraph||text.preferredWidth<=e.width+.5f)&&text.preferredHeight<=e.height+.5f,"Text bounds "+locale+"/"+width+"/"+state+"/"+e.id);Check(e.text.All(c=>char.IsWhiteSpace(c)||text.font.HasCharacter(c)),"Glyphs "+e.id);}
                }}}finally{GameLocale.Select(old);UnityEngine.Object.DestroyImmediate(go);}
            });
            report.status=report.failures.Count==0?"PASS_NATIVE_RAIN_CUP":"FAIL_NATIVE_RAIN_CUP";string output=Path.GetFullPath("../Verification/Evidence/RainCup");Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"Native_Checks.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(report.failures.Count==0?0:1);
        }
    }
}
#endif
